// ============ GA4 概览 KPI ============
function Ga4OverviewCard({ overview }: { overview: Ga4HookReturnType['overview'] }) {
  if (overview.loading) {
    return (
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {[0, 1, 2, 3].map((i) => (
          <Card key={i} className="border-border/40 bg-card">
            <CardContent className="p-5 animate-pulse">
              <div className="w-10 h-10 bg-muted/30 rounded-lg mb-3" />
              <div className="h-6 bg-muted/30 rounded w-1/2 mb-1" />
              <div className="h-3 bg-muted/20 rounded w-3/4" />
            </CardContent>
          </Card>
        ))}
      </div>
    );
  }

  if (overview.error) {
    return (
      <Card className="border-destructive/30 bg-destructive/5">
        <CardContent className="py-6 text-center">
          <AlertTriangle className="size-8 text-destructive mx-auto mb-2" />
          <p className="text-sm font-medium text-destructive">Failed to load GA4 data</p>
          <p className="text-xs text-muted-foreground mt-1">{overview.error}</p>
        </CardContent>
      </Card>
    );
  }

  const data = overview.data;
  if (!data) return null;

  const kpis = [
    {
      label: 'Total Sessions (30d)',
      value: data.totalSessions.toLocaleString(),
      icon: BarChart3,
      color: 'text-primary',
      bg: 'bg-primary/10',
      sub: `Users: ${data.totalUsers.toLocaleString()}`,
    },
    {
      label: 'Today Sessions',
      value: data.todaySessions.toLocaleString(),
      icon: CalendarClock,
      color: 'text-chart-2',
      bg: 'bg-chart-2/10',
      sub: `Users: ${data.todayUsers.toLocaleString()}`,
    },
    {
      label: 'Bounce Rate',
      value: `${data.bounceRate}%`,
      icon: Activity,
      color: 'text-chart-3',
      bg: 'bg-chart-3/10',
      sub: '30-day average',
    },
    {
      label: 'Avg. Duration',
      value: formatDuration(data.avgDurationSeconds),
      icon: TrendingUp,
      color: 'text-chart-4',
      bg: 'bg-chart-4/10',
      sub: 'per user',
    },
  ];

  return (
    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
      {kpis.map((kpi, idx) => {
        const Icon = kpi.icon;
        return (
          <Card key={kpi.label} className="border-border/40 bg-card">
            <CardContent className="p-5">
              <div className="flex items-center justify-between mb-3">
                <div className={`w-10 h-10 rounded-lg ${kpi.bg} flex items-center justify-center`}>
                  <Icon className={`size-5 ${kpi.color}`} />
                </div>
              </div>
              <div className="text-2xl font-bold text-foreground mb-1 tabular-nums">
                {kpi.value}
              </div>
              <div className="text-xs text-muted-foreground">{kpi.label}</div>
              <div className="text-[10px] text-muted-foreground/80 mt-2 line-clamp-1">
                {kpi.sub}
              </div>
            </CardContent>
          </Card>
        );
      })}
    </div>
  );
}

function formatDuration(seconds: number): string {
  const mins = Math.floor(seconds / 60);
  const secs = Math.floor(seconds % 60);
  if (mins === 0) return `${secs}s`;
  return `${mins}m ${secs}s`;
}

// ============ GA4 7 天趋势 ============
function Ga4TrendCard({ overview }: { overview: Ga4HookReturnType['overview'] }) {
  return (
    <Card className="lg:col-span-2 border-border/40 bg-card">
      <CardHeader className="pb-2">
        <CardTitle className="text-base flex items-center gap-2">
          <LineChart className="size-4 text-primary" />
          7-Day Sessions Trend
        </CardTitle>
      </CardHeader>
      <CardContent>
        {overview.loading ? (
          <div className="h-48 flex items-center justify-center">
            <RefreshCw className="size-5 text-muted-foreground/30 animate-spin" />
          </div>
        ) : overview.error ? (
          <div className="h-48 flex flex-col items-center justify-center text-center py-8">
            <AlertTriangle className="size-6 text-destructive/60 mb-2" />
            <p className="text-xs text-muted-foreground">{overview.error}</p>
          </div>
        ) : overview.data?.dailyTrend?.every((d) => d.sessions === 0) ? (
          <div className="py-12 text-center">
            <BarChart3 className="size-8 text-muted-foreground/30 mx-auto mb-3" />
            <p className="text-sm text-muted-foreground">No data</p>
          </div>
        ) : (
          <div className="flex items-end gap-2 md:gap-3 h-48 pt-4">
            {overview.data?.dailyTrend.map((d, i) => {
              const max = Math.max(1, ...overview.data.dailyTrend.map((x) => x.sessions));
              const heightPct = (d.sessions / max) * 100;
              const dateLabel = d.date.slice(5);
              return (
                <div key={d.date} className="flex-1 flex flex-col items-center gap-2">
                  <div className="text-xs font-medium tabular-nums text-foreground/80">
                    {d.sessions || 0}
                  </div>
                  <div className="w-full flex-1 flex items-end">
                    <div
                      className="w-full bg-primary/80 rounded-t-sm transition-all duration-300"
                      style={{
                        height: `${heightPct}%`,
                        minHeight: d.sessions > 0 ? '4px' : '2px',
                        opacity: d.sessions > 0 ? 1 : 0.2,
                      }}
                    />
                  </div>
                  <div className="text-[10px] text-muted-foreground tabular-nums">
                    {dateLabel}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

