// ============ GA4 设备类型 ============
function Ga4DevicesCard({ devices }: { devices: Ga4HookReturnType['devices'] }) {
  const items = devices.data?.devices || [];

  const getDeviceIcon = (cat: string) => {
    const lower = cat.toLowerCase();
    if (lower.includes('mobile')) return Smartphone;
    if (lower.includes('tablet')) return Tablet;
    return Monitor;
  };

  return (
    <Card className="border-border/40 bg-card">
      <CardHeader className="pb-2">
        <CardTitle className="text-base flex items-center gap-2">
          <Monitor className="size-4 text-primary" />
          Device Categories
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-3">
        {devices.loading ? (
          <div className="py-8 flex justify-center">
            <RefreshCw className="size-5 text-muted-foreground/30 animate-spin" />
          </div>
        ) : devices.error ? (
          <div className="py-6 text-center">
            <p className="text-xs text-destructive/80">{devices.error}</p>
          </div>
        ) : items.length === 0 ? (
          <div className="py-8 text-center">
            <p className="text-sm text-muted-foreground">No data</p>
          </div>
        ) : (
          items.map((d, i) => {
            const Icon = getDeviceIcon(d.category);
            return (
              <div key={d.category}>
                <div className="flex items-center justify-between text-sm mb-1">
                  <div className="flex items-center gap-2">
                    <Icon className="size-4 text-muted-foreground" />
                    <span className="text-foreground capitalize">{d.category}</span>
                  </div>
                  <span className="tabular-nums text-muted-foreground">
                    {d.sessions} · {d.percent}%
                  </span>
                </div>
                <div className="w-full h-2 bg-muted/30 rounded-full overflow-hidden">
                  <div
                    className="h-full rounded-full"
                    style={{
                      width: `${d.percent}%`,
                      backgroundColor: getChartColor(i),
                    }}
                  />
                </div>
              </div>
            );
          })
        )}
      </CardContent>
    </Card>
  );
}

function getChartColor(index: number): string {
  const colors = [
    'hsl(355 90% 50%)',
    'hsl(25 90% 50%)',
    'hsl(55 90% 50%)',
    'hsl(85 90% 50%)',
    'hsl(115 90% 50%)',
    'hsl(180 80% 45%)',
    'hsl(210 80% 50%)',
    'hsl(270 70% 60%)',
    'hsl(310 70% 55%)',
    'hsl(340 70% 55%)',
  ];
  return colors[index % colors.length];
}
