/**
 * GA4 数据获取 Hook
 *
 * 通过 Cloudflare Worker 代理调用 GA4 Data API，
 * 获取网站访问统计数据并在后台展示。
 *
 * 配置：
 * - Worker 地址保存在 AnalyticsSettings.ga4ApiProxyUrl 中
 * - Worker 内部用 Service Account JWT 认证调用 GA4 API
 */

import { useCallback, useState } from 'react';
import { logger } from '@lark-apaas/client-toolkit-lite';

// ============ 数据类型 ============

export interface Ga4OverviewData {
  totalSessions: number;
  totalUsers: number;
  todaySessions: number;
  todayUsers: number;
  bounceRate: string;
  avgDurationSeconds: number;
  dailyTrend: { date: string; sessions: number }[];
}

export interface Ga4TopPageItem {
  path: string;
  views: number;
  percent: string;
}
export interface Ga4TopPagesData {
  pages: Ga4TopPageItem[];
  total: number;
}

export interface Ga4SourceItem {
  name: string;
  sessions: number;
  percent: string;
}
export interface Ga4SourcesData {
  sources: Ga4SourceItem[];
  total: number;
}

export interface Ga4CountryItem {
  country: string;
  users: number;
  percent: string;
}
export interface Ga4CountriesData {
  countries: Ga4CountryItem[];
  total: number;
}

export interface Ga4DeviceItem {
  category: string;
  sessions: number;
  percent: string;
}
export interface Ga4DevicesData {
  devices: Ga4DeviceItem[];
  total: number;
}

export type Ga4Endpoint = 'overview' | 'top-pages' | 'sources' | 'countries' | 'devices';

export interface Ga4DataState<T> {
  loading: boolean;
  error: string | null;
  data: T | null;
}

// ============ 单接口请求函数 ============

async function fetchGa4Endpoint<T>(proxyUrl: string, endpoint: Ga4Endpoint): Promise<T> {
  const base = proxyUrl.replace(/\/$/, '');
  const url = `${base}/api/ga4/${endpoint}`;

  const resp = await fetch(url, {
    method: 'GET',
    headers: { Accept: 'application/json' },
  });

  const text = await resp.text();
  let data: any;
  try {
    data = JSON.parse(text);
  } catch {
    throw new Error(`Invalid JSON response (${resp.status})`);
  }

  if (!resp.ok || !data.success) {
    throw new Error(data.error || data.details || `Request failed (${resp.status})`);
  }

  return data.data as T;
}

// ============ Hook ============

export function useGa4Data(proxyUrl: string) {
  const [overview, setOverview] = useState<Ga4DataState<Ga4OverviewData>>({
    loading: false,
    error: null,
    data: null,
  });
  const [topPages, setTopPages] = useState<Ga4DataState<Ga4TopPagesData>>({
    loading: false,
    error: null,
    data: null,
  });
  const [sources, setSources] = useState<Ga4DataState<Ga4SourcesData>>({
    loading: false,
    error: null,
    data: null,
  });
  const [countries, setCountries] = useState<Ga4DataState<Ga4CountriesData>>({
    loading: false,
    error: null,
    data: null,
  });
  const [devices, setDevices] = useState<Ga4DataState<Ga4DevicesData>>({
    loading: false,
    error: null,
    data: null,
  });

  const loadAll = useCallback(async () => {
    if (!proxyUrl) {
      const empty = { loading: false, error: null, data: null };
      setOverview(empty);
      setTopPages(empty);
      setSources(empty);
      setCountries(empty);
      setDevices(empty);
      return;
    }

    // 全部置为 loading
    const loadingState = { loading: true, error: null, data: null };
    setOverview(loadingState);
    setTopPages(loadingState);
    setSources(loadingState);
    setCountries(loadingState);
    setDevices(loadingState);

    // 并行请求，互不影响
    const results = await Promise.allSettled([
      fetchGa4Endpoint<Ga4OverviewData>(proxyUrl, 'overview'),
      fetchGa4Endpoint<Ga4TopPagesData>(proxyUrl, 'top-pages'),
      fetchGa4Endpoint<Ga4SourcesData>(proxyUrl, 'sources'),
      fetchGa4Endpoint<Ga4CountriesData>(proxyUrl, 'countries'),
      fetchGa4Endpoint<Ga4DevicesData>(proxyUrl, 'devices'),
    ]);

    const [overviewRes, pagesRes, sourcesRes, countriesRes, devicesRes] = results;

    if (overviewRes.status === 'fulfilled') {
      setOverview({ loading: false, error: null, data: overviewRes.value });
    } else {
      const msg = overviewRes.reason instanceof Error ? overviewRes.reason.message : String(overviewRes.reason);
      logger.error('[GA4] overview error: ' + msg);
      setOverview({ loading: false, error: msg, data: null });
    }

    if (pagesRes.status === 'fulfilled') {
      setTopPages({ loading: false, error: null, data: pagesRes.value });
    } else {
      const msg = pagesRes.reason instanceof Error ? pagesRes.reason.message : String(pagesRes.reason);
      logger.error('[GA4] top-pages error: ' + msg);
      setTopPages({ loading: false, error: msg, data: null });
    }

    if (sourcesRes.status === 'fulfilled') {
      setSources({ loading: false, error: null, data: sourcesRes.value });
    } else {
      const msg = sourcesRes.reason instanceof Error ? sourcesRes.reason.message : String(sourcesRes.reason);
      logger.error('[GA4] sources error: ' + msg);
      setSources({ loading: false, error: msg, data: null });
    }

    if (countriesRes.status === 'fulfilled') {
      setCountries({ loading: false, error: null, data: countriesRes.value });
    } else {
      const msg = countriesRes.reason instanceof Error ? countriesRes.reason.message : String(countriesRes.reason);
      logger.error('[GA4] countries error: ' + msg);
      setCountries({ loading: false, error: msg, data: null });
    }

    if (devicesRes.status === 'fulfilled') {
      setDevices({ loading: false, error: null, data: devicesRes.value });
    } else {
      const msg = devicesRes.reason instanceof Error ? devicesRes.reason.message : String(devicesRes.reason);
      logger.error('[GA4] devices error: ' + msg);
      setDevices({ loading: false, error: msg, data: null });
    }
  }, [proxyUrl]);

  return {
    overview,
    topPages,
    sources,
    countries,
    devices,
    loadAll,
  };
}
